target.css:
:root {
  --paper: #fffdf7;
  --ink: #30342b;
  --muted: #74776a;
  --line: #dedbcf;
  --sage: #e8eee3;
  --rose: #b65f66;
  --gold: #d7a93d;
  --umber: #8a674d;
}

.dye-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.title-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 21px;
  line-height: 1.15;
  font-weight: 700;
}

.batch {
  padding: 5px 9px;
  background: var(--sage);
  border-radius: 999px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

.swatch-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 14px 0;
}

.swatch {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.color-chip {
  display: block;
  height: 42px;
  border-radius: 8px;
}

.madder .color-chip {
  background: var(--rose);
}

.weld .color-chip {
  background: var(--gold);
}

.walnut .color-chip {
  background: var(--umber);
}

.swatch-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

h2 {
  font-size: 13px;
  line-height: 1.2;
  font-weight: 700;
}

.swatch-info p,
.card-footer p {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

button {
  padding: 7px 11px;
  border: 1px solid var(--ink);
  border-radius: 8px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

